// Dos formas de replicar un clúster entre costa este y costa oeste.
// La ventana de 43 s es el dato de GitHub; el ritmo de escrituras es inventado.
function azar(semilla) {
  let s = semilla >>> 0;
  return () => (s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 4294967296;
}

function simular(modo) {
  const r = azar(7);
  const VENTANA = 43;          // segundos sin conexión entre las dos costas
  let soloEnEste = 0;          // escrituras que el oeste nunca vio
  let rechazadas = 0;          // escrituras que el este se negó a aceptar
  for (let seg = 0; seg < VENTANA; seg++) {
    const n = 15 + Math.floor(r() * 16);   // 15 a 30 escrituras por segundo
    if (modo === "asincrona") soloEnEste += n;
    else rechazadas += n;
  }
  return { modo, soloEnEste, rechazadas };
}

const a = simular("asincrona");
const s = simular("sincrona");
console.log("Réplica asincrónica (el este confirma sin esperar al oeste):");
console.log("  escrituras aceptadas solo en el este:", a.soloEnEste);
console.log("  escrituras rechazadas:", a.rechazadas);
console.log("  si el oeste se promueve a líder, hay dos historias distintas");
console.log("Réplica sincrónica (el este espera la confirmación del oeste):");
console.log("  escrituras aceptadas solo en el este:", s.soloEnEste);
console.log("  escrituras rechazadas durante 43 s:", s.rechazadas);
console.log("  no hay dos historias; el costo fue no poder escribir");

// Retroceso de una expresión regular. Patrón simplificado del apéndice de Cloudflare: x.*.*=.*
// Texto sin signo "=": el motor prueba todas las formas de repartir los caracteres entre los dos ".*".
function pasos(texto) {
  let n = 0;
  // Emulación explícita de x.*.*=.* para contar intentos (no usa el motor de JS).
  const largo = texto.length;
  for (let a = 0; a <= largo; a++) {         // cuánto se come el primer .*
    for (let b = a; b <= largo; b++) {       // cuánto se come el segundo .*
      n++;
      if (texto[b] === "=") return { n, hallado: true };
    }
  }
  return { n, hallado: false };
}
for (const largo of [10, 100, 1000, 5000]) {
  const t = "x" + "a".repeat(largo);
  const r = pasos(t);
  console.log(String(largo).padStart(5), "caracteres sin '=' ->", r.n.toLocaleString("es-AR"), "intentos");
}
